// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 warpTime) public {
        vm.warp(1000);
        vm.deal(address(this), 10 ether);
        vm.prank(address(this));
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok, "setup1 failed");

        vm.assume(warpTime <= 1001);
        vm.warp(warpTime);

        vm.deal(address(this), 10 ether);
        vm.prank(address(this));
        (bool success,) = address(c).call{value: 10 ether}("");

        assertTrue(!success);
    }
}
